let occupations = [];
if (data.worksWithChildren === "yes") {
  occupations = data.worksWithChildrenOccupations;
} else if (data.worksInUnderservedCommunity === "yes") {
  occupations = data.worksInUnderservedCommunitiesOccupations;
}

values = [...occupations].sort((a, b) => a.localeCompare(b));
